import SwiftUI
struct LoginView:View{
  @State var email="";@State var pwd="";@State var msg=""
  var body:some View{
    VStack{TextField("email",text:$email).textFieldStyle(.roundedBorder)
      SecureField("password",text:$pwd).textFieldStyle(.roundedBorder)
      Button("Login"){Task{await go()}}
      Text(msg)}.padding()}
  func go()async{
    var req=URLRequest(url:URL(string:"{{api_url}}/login")!)
    req.httpMethod="POST";req.setValue("application/json",forHTTPHeaderField:"Content-Type")
    req.httpBody=try?JSONEncoder().encode(["email":email,"password":pwd])
    do{let(_,r)=try await URLSession.shared.data(for:req)
      msg=(r as?HTTPURLResponse)?.statusCode==200 ?"ok":"fail"}catch{msg="err"}}}
